changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS "user".payments (
    id             UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    amount         DOUBLE PRECISION,
    user_id        UUID,
    payment_method TEXT,
    created_by     UUID,
    updated_by     UUID,
    created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_idx_payments_user ON "user".payments(user_id);
CREATE INDEX IF NOT EXISTS user_idx_payments_method ON "user".payments(payment_method);
